---
import HeaderFloating from "../components/blocks/HeaderFloating.astro";
import HeroSplit from "../components/blocks/HeroSplit.astro";
---

<HeaderFloating
  brand="Fernhill Studio"
  links={[
    { label: "Work", href: "/work" },
    { label: "Practice", href: "/practice" },
    { label: "Journal", href: "/journal" },
    { label: "Contact", href: "/contact" },
  ]}
  action={{ label: "Start a project", href: "/contact" }}
/>
<main style="inline-size: min(72rem, 100% - 2.5rem); margin-inline: auto;">
  <HeroSplit
    title="Rooms that hold the light all day"
    lede="Fernhill is a four-person architecture studio designing homes and small workplaces around how sunlight moves through them."
    actions={[{ label: "See the work", href: "/work" }, { label: "How we work", href: "/practice" }]}
    image={{ src: "/gallery/atelier.svg", alt: "Sunlit studio interior with a tall arched window", width: 1200, height: 1500 }}
  />
</main>

---
import HeaderMinimal from "../components/blocks/HeaderMinimal.astro";
import HeroTypographic from "../components/blocks/HeroTypographic.astro";
---

<HeaderMinimal
  brand="Quarry Bread"
  links={[
    { label: "Menu", href: "/menu" },
    { label: "Wholesale", href: "/wholesale" },
    { label: "Visit", href: "/visit" },
  ]}
  action={{ label: "Order for Saturday", href: "/order" }}
/>
<main style="inline-size: min(72rem, 100% - 2.5rem); margin-inline: auto;">
  <HeroTypographic
    title="Slow-fermented bread, baked before the street wakes up"
    emphasis="before the street wakes up"
    actions={[{ label: "See this week's bakes", href: "/menu" }]}
    facts={["14 Mill Lane", "Wed–Sun · 7–2", "Since 2016"]}
  />
</main>

